const $=s=>document.querySelector(s), app=$('#app');
const nav=[['Overview','⌂'],['Music','♫'],['Business','◈'],['Charts','▥'],['Industry','◎'],['Clothing','◇'],['Lifestyle','⌂'],['Character','♙']];
const catalog=[['Satin after-hours shirt','Tops','👔',180],['Electric blue moto jacket','Jackets','🧥',620],['Wide-leg vintage denim','Trousers','👖',240],['Midnight leather boots','Shoes','👢',390],['Studio bucket hat','Hats','🧢',95],['Archive wool overcoat','Coats','🧥',850],['Chain reaction necklace','Jewelry','⛓️',320],['Golden hour shades','Accessories','🕶️',140],['Tour-ready set','Outfits','🪩',700],['Platinum signet ring','Jewelry','💍',480],['Graphic tour tee','Tops','👕',110],['Starburst tattoo','Tattoos','✦',200],['Cargo runway pants','Trousers','👖',285],['Diamond ear cuffs','Jewelry','✨',260],['Retro varsity jacket','Jackets','🥼',540],['Designer shoulder bag','Accessories','👜',760]];
const initialArtists=[['Maya Sol','R&B',82],['Jett Monroe','Hip-hop',76],['The Halos','Pop',71],['Nico Vale','Alternative',68],['Sienna Rose','Pop',64],['Kilo North','Hip-hop',62],['June Wilder','Country',58],['Velvet Static','Rock',56],['Luna March','R&B',53]];
const tones=['#f1c7a6','#d99c74','#ad704e','#754a37','#f4d2bc','#b98261'];
const styles=['Slick curls','Cropped waves','Long braids','Soft locs','Classic bob','Freeform'];
let slots=JSON.parse(localStorage.getItem('encoreSaves')||'[]'), activeId=null, section='Overview', filter='All', toastTimer;
function persist(){localStorage.setItem('encoreSaves',JSON.stringify(slots))}function getSave(){return slots.find(x=>x.id===activeId)}
function avatar(c=getSave()){if(!c)return '';let tone=c?.tone||tones[1], hair=c?.hair||styles[0], shirt=c?.outfitColor||'#6d57d6';let hairShape=hair==='Long braids'?'<path d="M61 79 Q49 145 70 179 M133 78 Q149 143 129 179" stroke="#251e22" stroke-width="12" fill="none"/>':hair==='Classic bob'?'<path d="M54 68 Q59 27 99 30 Q143 31 143 78 L139 130 Q124 119 121 77 Q93 94 61 78 L58 128Z" fill="#251e22"/>':hair==='Freeform'?'<path d="M56 77 Q39 38 68 42 Q69 16 93 34 Q114 17 127 40 Q160 35 143 76 L133 97 64 96Z" fill="#251e22"/>':'<path d="M57 77 Q54 31 99 29 Q145 29 143 77 Q124 60 119 51 Q93 72 62 70Z" fill="#251e22"/>';return `<svg class="avatar-svg" viewBox="0 0 200 245" xmlns="http://www.w3.org/2000/svg"><ellipse cx="101" cy="231" rx="71" ry="10" fill="#473b7018"/><path d="M52 158 Q54 134 76 129 L100 145 124 129 Q148 136 151 158 L169 235 31 235Z" fill="${shirt}"/><path d="M82 112h37v35q-17 19-37 0z" fill="${tone}"/><ellipse cx="100" cy="83" rx="42" ry="52" fill="${tone}"/>${hairShape}<path d="M81 86h9M111 86h9" stroke="#33231f" stroke-width="3" stroke-linecap="round"/><path d="M93 105q8 6 16 0" stroke="#8c4c48" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M80 159l20 19 20-19" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="2"/></svg>`}
function age(c){return Math.max(18,Math.floor((new Date(`${c.birth||'2000-01-01'}T00:00:00`).getTime()-new Date('2000-01-01').getTime())/(-31557600000))+c.year-2000)}
function money(n){return '$'+Math.floor(n).toLocaleString()}
function newCareer(data={}){let c={id:Date.now().toString(),first:data.first||'Alex',last:data.last||'Rivera',stage:data.stage||'Nova',birth:data.birth||'2002-06-15',year:+data.year||2024,week:1,location:data.location||'New York',tone:data.tone||tones[1],hair:data.hair||styles[0],outfitColor:'#6d57d6',energy:100,heat:12,cash:4500,net:4500,popularity:8,level:'Independent artist',releases:[],feed:[],owned:[],favorites:[],equipped:'Everyday look',charts:initialArtists.map((a,i)=>({name:a[0],genre:a[1],score:a[2]+Math.random()*9,delta:i%2?1:-1,title:['Midnight Drive','Paper Crown','Blue Hour','Golden','Afterglow','No Sleep','Home Again','Static Bloom','Moonlit'][i],artist:true})),settings:{}};slots.push(c);activeId=c.id;persist();section='Overview';render()}
function menu(){app.innerHTML=`<div class="menu-screen"><div class="menu-art"><div class="menu-disc"></div><div class="floating-card float-one">#01 · THIS WEEK<span>Hot 100 · “Afterglow”</span></div><div class="floating-card float-two">NEW RELEASE<span>Your story starts here</span></div></div><div class="menu-left"><div class="menu-brand"><span class="brand-mark">♫</span> ENCORE</div><div class="eyebrow" style="color:#a7a69d">THE MUSIC CAREER SIMULATOR</div><h1 class="menu-title">Make<br>some <em>noise.</em></h1><p class="menu-copy">From your first late-night demo to the song everybody knows. Build a career, shape the sound, and write your name into music history.</p><div class="menu-actions"><button class="btn btn-lime primary" data-action="create">＋ &nbsp; Start a career</button><button class="btn btn-light" data-action="play">▶ &nbsp; Play</button><button class="btn btn-light" data-action="saves">▤ &nbsp; Load career</button><button class="btn btn-light" data-action="settings">⚙ &nbsp; Settings</button></div><div class="menu-note">${slots.length} CAREER SAVE${slots.length===1?'':'S'} · YOUR STORY, YOUR SOUND</div></div></div>`}
function header(c){return `<header class="topbar"><div class="brand"><span class="brand-mark">♫</span> ENCORE</div><div class="topmeta"><div class="meta-item"><span class="eyebrow">CAREER</span><span class="meta-value">${c.first} ${c.last}</span></div><div class="meta-item"><span class="eyebrow">YEAR · WEEK</span><span class="meta-value">${c.year} · ${c.week}</span></div><div class="meta-item"><span class="eyebrow">ENERGY</span><span class="meta-value">⚡ ${c.energy}%</span></div><div class="meta-item"><span class="eyebrow">HEAT</span><span class="meta-value">${c.heat}°</span></div></div><div class="top-right"><span class="pill"><span class="dot"></span>${money(c.cash)}</span><span class="save-chip">NET ${money(c.net)}</span><button class="icon-btn" title="Saves" data-action="saves">▤</button><button class="icon-btn" title="Menu" data-action="menu">↗</button></div></header>`}
function navHtml(){return `<aside class="sidebar"><div class="eyebrow nav-label">YOUR WORLD</div>${nav.map(([n,i])=>`<button class="nav-btn ${section===n?'active':''}" data-section="${n}"><span class="nav-icon">${i}</span>${n}</button>`).join('')}<div class="side-bottom"><div class="eyebrow">WEEK ${getSave().week}</div><p>Every move you make shapes the story. Rest, create, or make your next big move.</p><button class="btn btn-dark btn-small" data-action="advance">Advance week →</button></div></aside>`}
function pageHead(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${getSave().year} · WEEK ${getSave().week}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function stat(label,value,foot){return `<div class="card stat-card"><div class="stat-label">${label}</div><div class="stat-num">${value}</div><div class="stat-foot">${foot}</div></div>`}
function feedItems(c){let base=c.feed.slice(-5).reverse();if(!base.length)base=[{icon:'✦',title:'A new voice is emerging on the independent scene.',time:'Industry wire · this week'},{icon:'♫',title:'The charts are shifting. Make your next move count.',time:'Encore daily · this week'},{icon:'◈',title:'Labels are scouting for fresh sounds this season.',time:'Industry wire · this week'}];return base.map(x=>`<div class="feed-item"><div class="feed-icon">${x.icon}</div><div><strong>${x.title}</strong><small>${x.time}</small></div></div>`).join('')}
function releases(c){if(!c.releases.length)return `<div class="empty">♫<strong>Nothing out in the world. Yet.</strong>Your debut is just one song away.</div>`;return `<div class="release-list">${c.releases.slice(-4).reverse().map((r,i)=>`<div class="release-item"><div class="cover">${r.type==='Album'?'💿':'♫'}</div><div class="release-info"><strong>${r.title}</strong><small>${r.type} · ${r.genre} · ${r.streams.toLocaleString()} streams</small></div><div class="release-rank">${r.rank?`#${r.rank}`:'—'}</div></div>`).join('')}</div>`}

