function render(){let c=getSave();if(!c){menu();return}let body=section==='Overview'?dashboard(c):section==='Music'?musicPage(c):section==='Charts'?chartsPage(c):section==='Clothing'?clothingPage(c):section==='Industry'?industryPage(c):section==='Business'?businessPage(c):section==='Lifestyle'?lifestylePage(c):section==='Character'?characterPage(c):settingsPage();app.innerHTML=`<div class="app">${header(c)}<div class="layout">${navHtml()}<main class="main">${body}</main></div></div>`}
function modal(title,sub,content,actions=''){let old=$('#modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">ENCORE · YOUR STORY</div><h2>${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close">×</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`)}
function createModal(){modal('Start a new career','Make the artist you want the world to know.',`<form id="careerForm"><div class="form-grid"><div class="field"><label>First name</label><input name="first" placeholder="First name" required maxlength="24"></div><div class="field"><label>Last name</label><input name="last" placeholder="Last name" required maxlength="24"></div><div class="field full"><label>Stage name <span style="color:var(--muted);font-weight:400">— independent from your real name</span></label><input name="stage" placeholder="Your artist name" required maxlength="24"></div><div class="field"><label>Birth date</label><input type="date" name="birth" value="2002-06-15" required></div><div class="field"><label>Starting year</label><select name="year">${[1970,1980,1990,2000,2010,2020,2024].map(y=>`<option ${y===2024?'selected':''}>${y}</option>`).join('')}</select></div><div class="field full"><label>Starting location</label><select name="location">${['New York','Los Angeles','Atlanta','London','Toronto','Chicago','Nashville','Detroit','Miami','Seattle'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Skin tone</label><div class="swatches">${tones.map((t,i)=>`<button type="button" class="swatch ${i===1?'selected':''}" data-tone="${t}" style="background:${t}"></button>`).join('')}</div><input type="hidden" name="tone" value="${tones[1]}"></div><div class="field"><label>Hairstyle</label><select name="hair">${styles.map(x=>`<option>${x}</option>`).join('')}</select></div></div></form>`,`<button class="btn btn-light" data-action="close">Cancel</button><button class="btn btn-purple" data-action="submit-career">Begin your story →</button>`)}
